SELECT ?airport ?name ?value WHERE {
  ?airport a <http://www.semanticweb.org/ontologies/airport_ontology#Airport> .
  ?airport <http://www.semanticweb.org/ontologies/airport_ontology#airportName> ?name .
  ?airport <http://www.semanticweb.org/ontologies/airport_ontology#elevationFt> ?value .
  FILTER(?value > 2000)
} ORDER BY DESC(?value) LIMIT 10

